      if (proxy) {
        proxy.setEnabled(false);
        proxy.visibility = 0;
      }
      this._partVisibility[index] = 0;
      const removedState = this._streamingStates.find((s) => s.partIndex === index);
      if (removedState) {
        removedState.removed = true;
      }
      this._partSplatRanges[index] = [];
