        this._hasStreamingPart = false;
        this._tombstonedPartIndices.clear();
        this._refreshStreamingShState();
        this._useMrtAtlas = false;
        this._useRGBACovariants = !this.getEngine().isWebGPU && this.getEngine().version === 1;
